public class GenerationalTuningDemo {
    // VM Arguments for tuning generational sizes:
    // -Xms4g -Xmx4g -XX:NewRatio=2 -XX:SurvivorRatio=8 -XX:MaxTenuringThreshold=15

    public static void main(String[] args) {
        // These objects will die in Eden, triggering rapid Minor GCs
        for (int i = 0; i < 1_000_000; i++) {
            byte[] shortLivedAllocation = new byte[1024]; // 1KB
        }

        // Long-lived cache structure, destined for Old Generation promotion
        java.util.List<byte[]> tenuredCache = new java.util.ArrayList<>();
        for (int i = 0; i < 10_000; i++) {
            tenuredCache.add(new byte[1024 * 1024]); // 1MB each
        }

        System.out.println("Allocations complete. Tenured cache size: " + tenuredCache.size());
    }
}
